(function(root,factory){if(typeof module==='object'&&module.exports)module.exports=factory();else root.UnfallxHelp=factory();})(typeof globalThis!=='undefined'?globalThis:this,function(){'use strict';
const topics=[{"id":"dateien-entfernen","title":"Fotos und PDFs entfernen oder wiederherstellen","group":"Fälle & Unterlagen","roles":["partner","admin","appraiser"],"summary":"Einzelne Dateien korrigieren, ohne den ganzen Fall zu löschen.","steps":["Öffne den Fall und gehe zu Fotos oder PDFs & Dokumente. Klicke bei einer Datei auf Entfernen. Bei Fotos geht das auch über die große Vorschau.","Bestätige den Dateinamen. Die Datei verschwindet für beide Seiten aus der aktiven Akte und aus ZIP-Downloads. Die Änderung steht im Verlauf.","Unter PDFs & Dokumente findest du Entfernte Dateien. Über Wiederherstellen holst du das Original zurück. Firmenunterlagen haben einen eigenen Papierkorb in ihrer Dokumentenablage.","Bei einem Foto mit Markierungen entfernst du zuerst die markierte Kopie und danach bei Bedarf das Original. Zum Wiederherstellen gilt die umgekehrte Reihenfolge. Während ein persönlicher Kundenzugang aktiv ist oder noch übernommen werden muss, bleiben die Unterlagen gesperrt.","Partner können eigene Unterlagen während der Aufnahme oder einer Rückfrage korrigieren. Nach Einreichung bittet der Partner UNFALLX um Korrektur. Versandte Gutachten, freigegebene Rechnungen und Originale einer autoiXpert-Übergabe bleiben dokumentiert.","Fall löschen in der Fallablage betrifft dagegen nur die eigene Fallliste; dadurch werden keine Dateien entfernt."],"note":"Der Papierkorb ist keine endgültige Datenlöschung und gibt keinen Speicher frei. Bereits versandte oder heruntergeladene Kopien werden nicht zurückgerufen. Endgültige Löschanfragen bearbeitet UNFALLX nach Prüfung der Aufbewahrungspflichten.","links":[]},{"id":"orientierung","title":"Welcher Zugang ist der richtige?","group":"Start & Zugang","roles":["partner","admin","appraiser"],"summary":"Zwei Arbeitsbereiche, ein gemeinsamer Fallprozess.","steps":["Partnerportal: app.unfallx.com ist der Arbeitsplatz für Partnerbetriebe. Hier erfasst du Schäden, übermittelst Fotos und Dokumente und verfolgst den Bearbeitungsstand. Das funktioniert auch auf dem Handy.","Internes Dashboard: admin.unfallx.com ist ausschließlich für UNFALLX und das freigeschaltete interne Team bestimmt. Hier werden die eingereichten Partnerfälle geprüft, bearbeitet und an autoiXpert übergeben. Neue Fälle werden ausschließlich von freigeschalteten Partnern angelegt.","Melde dich im passenden Bereich mit deinem Konto an. Ein Partnerkonto eröffnet keinen internen Zugang. Interne Teammitglieder erhalten ihre Einladung durch die Administration.","Im Partnerportal findest du Übersicht, Schaden aufnehmen, Meine Fälle und Vergütung. Profil & Firma und Hilfe bleiben direkt erreichbar. Verlauf, Rückfragen, Fotos, PDFs und Nachrichten stehen direkt im Fall. Firmenunterlagen findest du unter Profil & Firma."],"note":"Fahrzeughalter erhalten bei aktivierten und bestätigten Benachrichtigungen einen Statuslink. Dafür ist kein eigenes Privatkundenportal vorgesehen.","links":[]},{"id":"registrierung","title":"Partnerkonto registrieren & freischalten","group":"Start & Zugang","roles":["partner"],"summary":"E-Mail bestätigen und die Freigabe des Betriebs abwarten.","steps":["Öffne „Als Partner registrieren“ und trage Unternehmensart, Firmenname, Ansprechpartner, vollständige Geschäftsanschrift, Telefonnummer und geschäftliche E-Mail ein. Verwende eine Adresse, auf die du persönlich zugreifen kannst.","Lege dein eigenes Passwort fest und beachte die angezeigten Passwortanforderungen. Lies die Nutzungs- und Datenschutzhinweise und sende die Registrierung einmal ab.","Öffne die Bestätigungs-E-Mail im angegebenen Postfach und bestätige den Zugang über den dortigen Link. Prüfe gegebenenfalls Spam und die Schreibweise der E-Mail-Adresse.","UNFALLX prüft den Betrieb und stimmt die Zusammenarbeit ab. Erst nach der Freischaltung kannst du neue Fälle einreichen. „Prüfung ausstehend“ bedeutet, dass diese Freigabe noch fehlt."],"note":"Ein bestätigtes Postfach und ein freigeschalteter Betrieb sind zwei getrennte Schritte.","links":[["Registrierung öffnen","/registrieren"]]},{"id":"login","title":"Anmelden, Passwort & fehlende E-Mails","group":"Start & Zugang","roles":["partner","admin","appraiser"],"summary":"So kommst du in deinen Arbeitsplatz zurück.","steps":["Öffne den Login deines Bereichs. Gib die registrierte E-Mail und dein eigenes Passwort ein. Das Augensymbol blendet das Passwort nur auf deinem Gerät ein oder aus.","Passwort vergessen? Öffne „Passwort festlegen / zurücksetzen“, fordere einen neuen Link an und nutze die neueste E-Mail. Lege das neue Passwort über den Link fest und melde dich anschließend erneut an.","Keine E-Mail erhalten? Prüfe Spam, Filter und das richtige Postfach. Kontrolliere die Adresse und fordere einen neuen Link an, wenn der alte abgelaufen ist. Wiederholte Klicks auf alte Links helfen nicht.","Bei einer zusätzlichen SMS-Abfrage gib den aktuellen Code ein. Ein Passwortwechsel schaltet die Zwei-Faktor-Anmeldung nicht aus. Bei Verlust des Telefons nutze einen unbenutzten Wiederherstellungscode.","Bei einer Meldung zum falschen Bereich öffne den passenden Zugang. Interne Mitarbeiter verwenden ausschließlich das Dashboard. Bleibt die Anmeldung erfolglos, nenne dem Support die E-Mail-Adresse und den Wortlaut der Fehlermeldung."],"note":"Gib Passwörter, SMS-Codes, Wiederherstellungscodes und persönliche Login-Links niemals weiter.","links":[["Login öffnen","/login"],["Passwort zurücksetzen","/passwort"]]},{"id":"interner-start","title":"Interne Einladung & erster Arbeitstag","group":"Start & Zugang","roles":["admin","appraiser"],"summary":"Interne Konten werden von der Administration eingeladen.","steps":["Öffne die persönliche Einladung im geschäftlichen Postfach. Sie ist 24 Stunden gültig. Richte deinen Zugang mit dem Link ein und verwende danach admin.unfallx.com.","Ist die Einladung abgelaufen oder nicht angekommen, bitte die Administration, unter „Internes Team“ eine neue Einladung zu senden. Registriere dich dafür nicht als Partnerbetrieb.","In der Übersicht siehst du deine verfügbaren Vorgänge. Ein interner Gutachter sieht nur zugewiesene Fälle. Eine leere Liste kann daher bedeuten, dass noch keine Zuweisung vorliegt.","Firmenfreigaben, Teamverwaltung, Provisionen und Zahlungen bleiben bei der Administration. Fehlende Menüpunkte bedeuten bei Teammitgliedern nicht automatisch einen Fehler."],"note":"","links":[]},{"id":"uebersicht","title":"Übersicht, Suche & Fallnummer","group":"Fälle & Aufnahme","roles":["partner","admin","appraiser"],"summary":"Den nächsten Schritt erkennen und den richtigen Vorgang öffnen.","steps":["Die Übersicht zeigt tatsächliche Eingänge, den Bearbeitungsstand und Rückfragen. Öffne „Meine Fälle“ im Partnerportal oder „Fälle“ im internen Dashboard. Suche nach Fallnummer, Kennzeichen oder Fahrzeug und nutze die Statusfilter.","Die Fallnummer kennzeichnet den Vorgang eindeutig. Verwende sie bei Rückfragen an UNFALLX. Ein Kennzeichen allein kann bei mehreren Schäden nicht eindeutig sein.","Öffne den Vorgang, um Angaben, Dateien, Nachrichten und Verlauf zu sehen. Rückfragen erfordern meist eine Ergänzung durch den einreichenden Betrieb.","Im Portal kannst du die Fallliste als CSV exportieren. Bewahre heruntergeladene Listen und Originale geschützt auf; sie enthalten personenbezogene Daten.","„Bei UNFALLX eingegangen“ erscheint erst nach bestätigter Übermittlung. Entwürfe sind noch nicht eingereicht. Eingang bedeutet, dass die Daten angekommen sind; die fachliche Prüfung erfolgt danach."],"note":"","links":[]},{"id":"erster-fall","title":"Neuen Fall anlegen & Entwurf speichern","group":"Fälle & Aufnahme","roles":["partner"],"summary":"Beginne mit den Angaben und ergänze die Unterlagen im selben Vorgang.","steps":["Wähle „Schaden aufnehmen“ direkt auf deiner Übersicht oder im Menü. Auf dem Handy erreichst du die Aufnahme jederzeit über „Aufnehmen“ in der unteren Leiste. Dein Betrieb muss dafür freigeschaltet sein.","Erfasse mindestens die zum Speichern angeforderten Basisangaben. Arbeite anschließend die Bereiche Auftraggeber, Fahrzeug, Unfall, Besichtigung und Kanzlei durch. Die Pflichtprüfung erfolgt vor der Einreichung.","Speichere deine Eingaben als Entwurf. Prüfe die Speicherbestätigung, bevor du die Seite verlässt oder zu einem anderen Vorgang wechselst.","Deine gespeicherten Vorgänge sind im Partnerportal am Computer und auf dem Handy verfügbar. Öffne „Meine Fälle“, um die Aufnahme fortzusetzen.","Vor der Übermittlung ergänze die offenen Angaben und lade die erforderlichen Originaldateien vollständig hoch. Erst danach „Fall einreichen“ wählen."],"note":"Ungespeicherte Eingaben sind nicht automatisch gesichert. Halte den Browser bei Verbindungsproblemen geöffnet.","links":[]},{"id":"auftraggeber","title":"Auftraggeber, Adresse & Bankverbindung","group":"Fälle & Aufnahme","roles":["partner","admin","appraiser"],"summary":"Hier stehen die Daten des Auftraggebers bzw. Fahrzeughalters – nicht automatisch die des einreichenden Betriebs.","steps":["Wähle die passende Art des Auftraggebers. Trage bei Unternehmen die Firma sowie den persönlichen Ansprechpartner mit Vor- und Nachnamen ein.","Erfasse Straße und Hausnummer, Postleitzahl und Ort getrennt. Ein vorhandenes Postfach kannst du zusätzlich angeben. Es ersetzt nicht die benötigte Anschrift.","Trage Telefonnummer und E-Mail sorgfältig ein. Prüfe die IBAN mit dem Auftraggeber; eine ähnlich aussehende, aber falsche Zeichenfolge kann die Abwicklung erschweren.","Übernimm die Angaben aus verlässlichen Unterlagen und lass unklare Daten klären. Verwende keine erfundenen Platzhalter, um die Pflichtprüfung zu umgehen."],"note":"","links":[]},{"id":"fahrzeug","title":"Fahrzeug, Eigentumsverhältnis & Vorschäden","group":"Fälle & Aufnahme","roles":["partner","admin","appraiser"],"summary":"Identifikation, wirtschaftliche Zuordnung und Zustand zusammen erfassen.","steps":["Trage Fahrzeug bzw. Modell, amtliches Kennzeichen und Fahrgestellnummer ein. Gleiche die Fahrgestellnummer mit dem Fahrzeugschein ab und kontrolliere schwer lesbare Zeichen.","Erfasse den abgelesenen Kilometerstand und den HU-Termin im vorgesehenen Monatsfeld. Lade zusätzlich den vollständigen und lesbaren Fahrzeugschein hoch.","Wähle Eigentum, Leasing, Finanzierung oder Finanzierung über Herstellerbank. Ergänze gegebenenfalls Leasinggeber oder finanzierende Bank im vorgesehenen Feld.","Gib die Vorsteuerabzugsberechtigung des Auftraggebers nach dessen Auskunft an. Diese Angabe bezieht sich nicht pauschal auf deinen eigenen Betrieb.","Gib an, ob Vorschäden vorhanden sind. Beschreibe bekannte Schäden und ihren Zustand nachvollziehbar. Ist der Zustand unbekannt, wähle die angebotene Angabe „Unbekannt“ und kläre ihn mit UNFALLX."],"note":"","links":[]},{"id":"unfall","title":"Unfalldaten, Gegner & Polizei","group":"Fälle & Aufnahme","roles":["partner","admin","appraiser"],"summary":"Unfallzeit und Gegnerkennzeichen gehören zur vollständigen Aufnahme.","steps":["Erfasse Unfalltag, Uhrzeit und den genauen Unfallort. Halte Unfallzeit und Besichtigungszeit auseinander; sie müssen nicht identisch sein.","Bei polizeilicher Aufnahme ergänze Aktenzeichen und Polizeibehörde. Trage die Angaben so ein, wie sie auf der polizeilichen Mitteilung stehen.","Erfasse das Kennzeichen des Unfallgegners. Ist es unbekannt, wähle ausdrücklich die Ausnahme für ein unbekanntes Gegnerkennzeichen bei bekanntem Polizeiaktenzeichen.","Diese Ausnahme setzt die Angaben zur Polizeiakte voraus. Ohne Gegnerkennzeichen und ohne die erforderlichen Polizeidaten bleibt der Vorgang ein Entwurf, bis die Informationen geklärt sind.","Name, Anschrift, Versicherung und Versicherungsnummer des Gegners sind ergänzende Angaben, soweit vorhanden. Verwechsle das Gegnerkennzeichen nicht mit dem eigenen Kennzeichen."],"note":"","links":[]},{"id":"besichtigung","title":"Besichtigung vollständig dokumentieren","group":"Fälle & Aufnahme","roles":["partner","admin","appraiser"],"summary":"Die Aufnahme soll auch später nachvollziehbar sein.","steps":["Erfasse die vollständige Besichtigungsanschrift mit Straße, Hausnummer, Postleitzahl und Ort sowie Tag und Uhrzeit der tatsächlichen Aufnahme.","Trage ein, wer das Fahrzeug besichtigt hat und zu welchem Betrieb diese Person gehört. Ergänze alle weiteren Anwesenden oder bestätige, dass nur die aufnehmende Person anwesend war.","Wähle den Zustand des Fahrzeugs: unzerlegt, teilweise zerlegt oder zerlegt. Dokumentiere sichtbare Teile und Schäden passend dazu.","Gib an, ob die Besichtigungsbedingungen ausreichend waren. Bei Einschränkungen beschreibe beispielsweise Licht, Platz oder fehlende Zugänglichkeit.","Gib an, ob Hilfsmittel verwendet wurden. Wähle zutreffende Hilfsmittel wie Hebebühne, Messlatte, Dellenentferner, Lackmessgerät, Diagnosegerät oder Beleuchtung; beschreibe andere Hilfsmittel im Zusatzfeld."],"note":"","links":[]},{"id":"kanzlei-auswahl","title":"Anwaltswahl, Auftrag & Kundenbenachrichtigung","group":"Fälle & Aufnahme","roles":["partner","admin","appraiser"],"summary":"Wünsche und Einverständnisse des Auftraggebers korrekt festhalten.","steps":["Wähle „Eigene Kanzlei“, Unterstützung durch eine UNFALLX-Partnerkanzlei oder die angebotene offene Auswahl, wenn die Entscheidung noch aussteht.","Bei einer eigenen Kanzlei erfasse deren Namen und Kontaktdaten. Ein Wunsch nach Vermittlung ist noch keine dokumentierte Übermittlung des Gutachtens.","Lade den unterschriebenen Auftrag bzw. die erforderliche Vollmacht hoch und bestätige die Berechtigung zur Übermittlung. Hake Einverständnisse nur an, wenn sie tatsächlich vorliegen.","Soll der Fahrzeughalter E-Mails und einen Statuslink erhalten, aktiviere dies mit dessen Einverständnis und kontrolliere die Empfängeradresse. Der Empfänger muss die Benachrichtigung zusätzlich über seine E-Mail bestätigen.","Eine Weitergabe an die Kanzlei erfolgt im internen Bearbeitungsablauf mit der entsprechenden Freigabe. Eine bloße Auswahl im Formular versendet noch kein Gutachten."],"note":"","links":[]},{"id":"fotos","title":"Viele Fotos & PDFs gemeinsam hochladen","group":"Dateien & Übermittlung","roles":["partner","admin","appraiser"],"summary":"Originaldateien werden übertragen, ohne sie für den Upload kleinzurechnen.","steps":["Ziehe alle Fotos und PDFs gemeinsam in die Uploadfläche oder wähle mehrere Dateien auf deinem Handy aus. Über „＋ Fotos & PDFs hinzufügen“ kannst du die Auswahl jederzeit ergänzen.","Fotos werden automatisch als Schadenfotos zugeordnet. Eine Einzelbeschriftung ist nicht nötig. Tippe auf eine Fotokachel oder „Fotos durchsehen“ und wische nach links oder rechts. Mit dem X entfernst du eine noch nicht übertragene Datei aus der Auswahl. „Fertig ×“ schließt die Vorschau.","Nur Fahrzeugschein und unterschriebener Auftrag brauchen die passende Dateiart. Wähle sie bei PDFs direkt aus. Ist die Unterlage fotografiert, öffne bei dieser Fotokachel „Als Dokument zuordnen“. Eine gemeinsame PDF mit beiden Unterlagen kannst du als kombiniertes Unterlagenpaket zuordnen.","Pro Fall sind bis zu 100 Dateien mit zusammen 750 MB möglich; jede Datei darf bis zu 25 MB groß sein. Unterstützt werden JPEG, PNG, WebP, HEIC und PDF. Andere Formate werden abgewiesen.","Starte das Hochladen bzw. Einreichen und beobachte den Fortschritt. Die App speichert die ausgewählten Originaldateien. Bereits in Messenger-Apps verkleinerte Bilder werden dadurch nicht wieder zu Originalen.","Lasse die Seite während der Übertragung geöffnet. Erst wenn alle Dateien als gespeichert angezeigt werden, ist der Upload vollständig. Eine kleine Vorschau dient nur der Anzeige; über „Original herunterladen“ erhältst du die gespeicherte Datei.","In der Fallakte unter „Fotos“ öffnest du die Galerie. „Alle Fotos herunterladen“ lädt die Originale als eine ZIP-Datei. Unter „PDFs & Dokumente“ kannst du alle freigegebenen Fotos und Unterlagen zusammen als ZIP herunterladen. Entpacke die ZIP in der Dateien-App oder auf deinem Computer. Bei einem unterbrochenen Download starte ihn erneut."],"note":"Zum Einreichen werden mindestens ein Schadenfoto, ein Fahrzeugschein und ein unterschriebener Auftrag benötigt. Die Zuordnung zur richtigen Dateiart zählt mit.","links":[]},{"id":"fotoqualitaet","title":"Welche Bilder werden benötigt?","group":"Dateien & Übermittlung","roles":["partner","admin","appraiser"],"summary":"Eine verständliche Fotoreihe spart Rückfragen.","steps":["Beginne mit Übersichtsaufnahmen aus mehreren Richtungen, damit Fahrzeug und Schadenbereich eingeordnet werden können. Fotografiere das Fahrzeug möglichst vollständig und scharf.","Ergänze mittlere Ansichten des betroffenen Bauteils und Nahaufnahmen der Beschädigung. Ein einzelnes Detailbild ohne räumlichen Zusammenhang reicht häufig nicht aus.","Dokumentiere Kennzeichen, Fahrgestellnummer und Kilometeranzeige lesbar. Fotografiere Dokumente vollständig einschließlich aller benötigten Seiten; vermeide abgeschnittene Ränder und Lichtreflexe.","Fotografiere bekannte Vorschäden getrennt und beschreibe sie im Formular. Nimm nur auf, was sich sicher und ohne zusätzliche Gefährdung erreichen lässt.","Prüfe die Bilder auf dem Handy vor dem Einreichen. Übertrage möglichst die Originale aus der Kamera bzw. Fotomediathek und keine Bildschirmfotos von bereits komprimierten Bildern."],"note":"Welche zusätzlichen Ansichten erforderlich sind, entscheidet UNFALLX anhand des konkreten Falls.","links":[]},{"id":"upload-probleme","title":"Upload abgebrochen, Datei fehlt oder ist zu groß","group":"Dateien & Übermittlung","roles":["partner","admin","appraiser"],"summary":"Den vorhandenen Vorgang fortsetzen und offene Dateien gezielt prüfen.","steps":["Bei fehlender Verbindung oder Zeitüberschreitung halte die Seite geöffnet und stelle eine stabile Verbindung her. Starte die noch offenen Übertragungen erneut, statt einen neuen Fall anzulegen.","Prüfe in der Uploadliste, welche Dateien bereits gespeichert sind. Nach einem Neuladen öffne zuerst die Fallakte und vergleiche die vorhandenen Dateinamen, bevor du fehlende Dateien erneut auswählst.","Bei „Datei zu groß“ oder ausgeschöpftem Falllimit kontaktiere UNFALLX für die Abstimmung. Komprimiere beweisrelevante Originalfotos nicht unbemerkt. Eine große PDF kann gegebenenfalls in vollständige, lesbare Teile getrennt werden.","Wird ein Dokument trotz Upload als fehlend markiert, kontrolliere seine Dateiart. In bearbeitbaren Fällen lässt sich die Zuordnung speichern. Ein Auftrag mit der allgemeinen Art „Dokument“ erfüllt nicht automatisch die Pflicht zum unterschriebenen Auftrag.","HEIC-Dateien können je nach Browser ohne Vorschau erscheinen. Prüfe den Dateieintrag und lade das Original herunter. Eine fehlende Miniatur allein bedeutet nicht, dass die Datei verloren ist."],"note":"","links":[]},{"id":"einreichen","title":"Prüfen, einreichen & Rückfragen ergänzen","group":"Dateien & Übermittlung","roles":["partner"],"summary":"Erst die erfolgreiche Übermittlung gibt den Fall an UNFALLX weiter.","steps":["Prüfe vor dem Einreichen die angezeigten Pflichtangaben und Dokumentanforderungen. Ergänze fehlende Angaben und kontrolliere die Übertragung aller Dateien.","Wähle „An UNFALLX einreichen“ und kontrolliere anschließend die Bestätigung und den neuen Status. Erst ein eingereichter Fall wird zur weiteren Bearbeitung übermittelt.","Kontrolliere danach die Fallnummer und den Status „Eingereicht“. Ein gespeicherter Entwurf oder „Bereit zur Übermittlung“ wurde noch nicht zwingend übergeben.","Nach der Einreichung übernimmt UNFALLX. Partner können den internen Bearbeitungsstand nicht beliebig setzen. Wenn UNFALLX eine Rückfrage öffnet, ergänze die angeforderten Angaben und Dateien im bestehenden Fall.","Schreibe deine Antwort in die Nachricht zum Vorgang und übermittle die Ergänzung mit der angebotenen Aktion. Der Verlauf zeigt, welche Schritte bereits durchgeführt wurden."],"note":"","links":[]},{"id":"bearbeitung","title":"Status verstehen: vom Entwurf bis zum Abschluss","group":"Zusammenarbeit","roles":["partner","admin","appraiser"],"summary":"Die Statusbezeichnung beschreibt den Arbeitsstand, nicht automatisch einen Zahlungseingang.","steps":["Entwurf → Aufnahme läuft → Bereit zur Übermittlung: Die Aufnahme wird vorbereitet. Der Partner kann die dafür vorgesehenen Vorbereitungsschritte selbst setzen.","Eingereicht → In Prüfung → Angenommen: Der Vorgang liegt bei UNFALLX. „Rückfrage“ bedeutet, dass Angaben, Bilder oder Unterlagen nachgereicht werden müssen. „Abgelehnt“ bedeutet, dass UNFALLX den Vorgang nicht übernimmt.","Gutachten in Arbeit → Gutachten freigegeben: Das interne Team erstellt und prüft das Gutachten. Eine Freigabe ist noch kein bestätigter Versand an die Kanzlei.","Gutachten versandt → Abgeschlossen: Der Versand ist dokumentiert; der Fall wird nach den erforderlichen Abschluss- und Abrechnungsschritten geschlossen.","Öffne die Fallakte für Nachrichten und den tatsächlichen Verlauf. Es werden nur die für deine Rolle und den aktuellen Stand zulässigen Folgeaktionen angeboten."],"note":"","links":[]},{"id":"status-aendern","title":"Status ändern – auch aus dem Entwurf","group":"Zusammenarbeit","roles":["admin","appraiser"],"summary":"Der Schalter befindet sich in der Fallakte im Abschnitt „Bearbeitung“.","steps":["Öffne die Fallübersicht und wähle den Vorgang. Tippe oben auf den Bearbeitungsstand oder auf den Reiter „Bearbeitung“. Auf kleinen Displays kannst du die Reiter seitlich verschieben.","Die Administration kann auch einen Entwurf öffnen und einen angebotenen Folgestatus auswählen. Für die endgültige Übergabe müssen die jeweils geprüften Pflichtdaten und Unterlagen vorliegen.","Wähle den nächsten zulässigen Status und ergänze die erforderliche Notiz oder Rückfrage. Speichere die Änderung und prüfe anschließend den Verlauf.","Interne Gutachter bearbeiten nur zugewiesene Fälle und erhalten nicht automatisch alle administrativen Aktionen. Soll ein noch nicht zugewiesener Entwurf übernommen werden, übernimmt zunächst die Administration.","Für „Gutachten freigegeben“ muss die Gutachten-PDF vorliegen. Für den Versand werden die Versandangaben und Freigaben geprüft. Zum Abschluss können offene Abrechnungs- oder Auszahlungsschritte relevant sein."],"note":"Eine abgewiesene Änderung wird nicht stillschweigend gespeichert. Lies die Fehlermeldung und behebe die genannte Voraussetzung.","links":[]},{"id":"nachrichten","title":"Rückfragen, Verlauf & Statuslink für den Kunden","group":"Zusammenarbeit","roles":["partner","admin","appraiser"],"summary":"Kommunikation bleibt beim richtigen Fall.","steps":["Öffne im Fall „Nachrichten“. Hier schreiben Partner und das zuständige UNFALLX-Team direkt miteinander. Du kannst bis zu sechs Fotos oder PDFs pro Nachricht auswählen oder hineinziehen. Die Originale werden ohne Qualitätsverlust gespeichert. Eine Nachricht nur mit Anhängen ist ebenfalls möglich.","Erst die bestätigte Meldung zeigt, dass die Nachricht eingegangen ist. Ist der Empfang unbestätigt, wähle erneut Senden: Dieselbe Nachricht wird geprüft, ohne ein Duplikat anzulegen. Lass die Seite dafür geöffnet. Noch nicht gesendete Nachrichten sind nicht dauerhaft lokal gesichert.","Über das × entfernst du einen Anhang aus deiner Nachrichtenauswahl. Bereits hochgeladene Originale bleiben in der Fallakte und lassen sich dort im Rahmen der Berechtigungen entfernen. Sprachnachrichten aus der iPhone-App kannst du im Gespräch anhören und als Original herunterladen. Chat-Anhänge gehören nicht zur autoiXpert-Übergabe.","Öffne „Nachrichten“, um die fallbezogenen Mitteilungen zu sehen. Ein Klick führt zur zugehörigen Schadenakte.","Im Partnerportal gliedert sich die Akte in Übersicht, Fotos, Dokumente und Nachrichten. Unter Nachrichten kannst du direkt zum Schaden schreiben.","Steht ein Fall auf „Rückfrage“, lies die Erläuterung und ergänze die benötigten Angaben oder Unterlagen. Eine bloße Nachricht allein ändert den Status nicht.","Der Verlauf hält Bearbeitungsschritte fest. E-Mail-Benachrichtigungen machen auf Änderungen aufmerksam; der vollständige Arbeitsstand steht im Portal.","Eine zusätzliche Kundenadresse erhält Benachrichtigungen nur nach entsprechender Freigabe und Bestätigung. Der persönliche Statuslink zeigt den freigegebenen Fortschritt, nicht den internen Arbeitsplatz oder fremde Fälle.","Nach dokumentierter Weitergabe an eine Kanzlei kann die Kundeninformation die hinterlegten Kanzleikontaktdaten enthalten. Prüfe deshalb die Zuordnung vor dem Versand.","Ist ein Statuslink abgelaufen oder widerrufen, muss UNFALLX den Zugang prüfen. Teile persönliche Statuslinks nicht öffentlich.","Fotovorschauen werden für schnelle Anzeige verkleinert. Über „Original öffnen“ bzw. „Original herunterladen“ erhältst du die unveränderte hochgeladene Datei."],"note":"Partner sehen nur Vorgänge und öffentliche Fallnachrichten ihres eigenen Betriebs. Interne Notizen bleiben dem UNFALLX-Team vorbehalten.","links":[]},{"id":"gutachten","title":"Gutachten erstellen, zuweisen & versenden","group":"Zusammenarbeit","roles":["admin","appraiser"],"summary":"Die Fallakte verbindet Prüfung, Gutachten-PDF und dokumentierten Versand.","steps":["Prüfe Auftraggeber, Fahrzeug, Unfall, Besichtigung, Auftrag und Dateien. Die Administration weist den Vorgang bei Bedarf einem internen Gutachter zu.","Stelle fehlende Informationen über eine Rückfrage zusammen. Übernimm den Fall in die Bearbeitung, sobald die erforderlichen Grundlagen vorliegen.","Erstelle das Gutachten fachlich mit dem dafür vorgesehenen Gutachtenwerkzeug. Das Dashboard selbst erstellt aus den Fotos nicht automatisch ein fertiges Sachverständigengutachten.","Lade die fertige PDF in der Fallakte mit der dafür vorgesehenen Gutachten-Funktion hoch. Prüfe die richtige Datei und setze anschließend die Freigabe.","Kontrolliere Kanzlei und Übermittlungsberechtigung. Führe den tatsächlichen Versand durch und dokumentiere ihn mit Versandreferenz und Bestätigung. Setze „Gutachten versandt“ erst nach diesem Schritt."],"note":"Eine Statusänderung allein ersetzt keinen tatsächlichen Versand an die Kanzlei.","links":[]},{"id":"abrechnung","title":"Partnervergütung & eigene Rechnung","group":"Abrechnung & Dokumente","roles":["partner"],"summary":"Die Konditionen werden pro Fall vereinbart.","steps":["Auf der Übersicht siehst du deine voraussichtlichen, auszahlbaren und ausgezahlten Provisionen. „Provisionen“ und „Abrechnung“ stehen direkt im Hauptmenü; mobil ist „Provision“ unten erreichbar.","Öffne den gewünschten Fall und tippe auf den Provisionsbetrag oder den Reiter „Vergütung“. Dort siehst du die Nettovergütung, die Vereinbarung und den Zahlungsstand.","Prüfe die Konditionen und bestätige die angebotene Vereinbarung im Vorgang. Ist noch kein Betrag vereinbart, stimme ihn mit UNFALLX ab.","Erst nach vollständigem Zahlungseingang des Gutachtenhonorars, dokumentiertem Gutachtenversand und den erforderlichen Vereinbarungen wird die Partnerrechnung ermöglicht.","Lade deine korrekte Rechnung im Fall unter „PDFs & Dokumente“ mit der Dateiart „Partnerrechnung (PDF)“ hoch. Diese Auswahl erscheint erst, wenn die Voraussetzungen erfüllt sind. Die Administration prüft sie und erfasst die Auszahlung nach der tatsächlichen Überweisung.","„Auszahlung erfasst“ dokumentiert die Überweisung durch UNFALLX. Die App führt selbst keine Banküberweisungen aus. Frage bei Unklarheiten mit der Fallnummer nach."],"note":"Es gibt keine automatisch geltende 50/50-Quote und keinen garantierten pauschalen Betrag.","links":[]},{"id":"abrechnung","title":"Provision festlegen, Zahlungen & Auszahlung","group":"Abrechnung & Dokumente","roles":["admin"],"summary":"Beträge in der Fallakte berechnen und den Zahlungsablauf dokumentieren.","steps":["Öffne den Fall über „Fälle“ oder „Abrechnung“. Tippe auf den Provisionsbetrag oben oder den Reiter „Vergütung“.","Trage Rechnungsnummer, Gutachtenhonorar, Netto-/Bruttogrundlage und Umsatzsteuer ein. Wähle unter „Provision berechnen als“ einen festen Nettobetrag in Euro oder einen Prozentanteil vom Nettohonorar. Ergänze die Umsatzsteuer des Partners und die individuelle Vereinbarung.","Kontrolliere die Vorschau und speichere mit „Provision & Rechnungsdaten speichern“. Der Partner sieht anschließend den Nettobetrag. Bei Änderungen an Betrag oder Vereinbarung muss er die Konditionen erneut bestätigen; nach Eingang einer Partnerrechnung sind die Beträge gesperrt.","Erfasse tatsächlich eingegangene Teil- oder Vollzahlungen mit Betrag, Buchungsdatum und Bankreferenz. Eine Teilzahlung ist noch kein vollständiger Zahlungseingang.","Nach Gutachtenversand, vollständiger Zahlung und Partnerbestätigung kann der Partner seine Rechnung hochladen. Prüfe Leistungsbezug, Empfänger, Betrag, Steuerangaben und Bankverbindung, bevor du sie freigibst.","Führe die Überweisung über das Bankkonto aus. Erfasse erst danach Auszahlungsdatum und Überweisungsreferenz im Dashboard und bestätige die tatsächlich erfolgte Zahlung."],"note":"Die App berechnet und dokumentiert. Sie löst keine Banküberweisung aus und ersetzt keine Prüfung der Rechnung.","links":[]},{"id":"dokumente","title":"Firmenunterlagen oder Unterlagen zum Fall?","group":"Abrechnung & Dokumente","roles":["partner","admin"],"summary":"Die beiden Ablagen haben unterschiedliche Zwecke und Grenzen.","steps":["Unter „Dokumente“ findest du die Unterlagen deiner Fälle. „Firmenunterlagen“ steht im Menü unter „Weitere Funktionen“. Das interne Dashboard zeigt nur die für deine Rolle freigegebenen Bereiche.","Fotos, Fahrzeugschein, Auftrag und Gutachten gehören direkt in die zugehörige Fallakte. Dort stehen sie dem berechtigten Bearbeitungsteam im Zusammenhang mit dem Vorgang zur Verfügung.","„Firmenunterlagen“ ist für zusätzliche Dokumente zwischen einem Partnerbetrieb und der Administration gedacht. Eine Datei darf hier höchstens 6 MB groß sein und muss eine PDF sein.","Die Administration wählt vor dem Hochladen „Nur Administration“ oder einen bestimmten Partnerbetrieb plus Administration. Partner sehen ausschließlich ihre zugeordneten Dokumente.","Suche nach Dateiname bzw. Partner und nutze „Herunterladen“. Diese Ablage wird weder Kunden noch anderen Partnerfirmen angezeigt. Allgemeine interne Gutachter erhalten dadurch keinen Zugriff.","Eine Gutachten-PDF, die nur hier liegt, erfüllt nicht die Gutachten-Voraussetzung der Fallakte. Lade sie für Freigabe und Versand in den richtigen Vorgang."],"note":"","links":[]},{"id":"empfehlungen","title":"Bestehende Empfehlungen","group":"Vergütung","roles":["partner"],"summary":"Bestehende Vereinbarungen bleiben erhalten.","steps":["Öffne Vergütung und dort Bestehende Empfehlungen.","Bereits zugeordnete Empfehlungen und angebotene Konditionen bleiben prüfbar und abrechenbar.","Neue Empfehlungslinks und neue Teilnahmen sind vorerst pausiert."],"note":"Die reguläre Partnervergütung je Gutachten ist davon unabhängig.","links":[]},{"id":"provisionen","title":"Empfehlungsprovisionen prüfen & auszahlen","group":"Verwaltung","roles":["admin"],"summary":"Empfehlung und Zahlungsnachweise vor dem Angebot prüfen.","steps":["Öffne unter „Weitere Funktionen“ den Bereich „Empfehlungsprovisionen“. Nach Gutachtenversand oder Abschluss werden zugeordnete Vorgänge zur Prüfung angezeigt.","Kontrolliere Empfehlung, Auftrag und vollständigen Zahlungseingang. Trage Provisionsbetrag, bezahltes Bruttohonorar, Rechnungsnummer und Buchungsreferenz korrekt ein.","Formuliere die konkrete Einzelvereinbarung einschließlich Steuer- und Abrechnungsgrundlage. Biete sie dem Vermittler an oder dokumentiere eine begründete Ablehnung.","Nach Annahme stimme den Abrechnungsbeleg ab und prüfe ihn. Erfasse die Auszahlung erst nach tatsächlicher Überweisung mit Datum, Bankreferenz und Belegreferenz.","Ein gegebenenfalls in der Fallakte zugeordneter Empfehlungscode ist von der Vergütungsvereinbarung mit dem fallübermittelnden Partner zu unterscheiden. Prüfe beide Grundlagen gesondert."],"note":"","links":[]},{"id":"partner","title":"Partnerfirmen prüfen & freischalten","group":"Verwaltung","roles":["admin"],"summary":"Die E-Mail-Bestätigung allein ersetzt keine Firmenfreigabe.","steps":["Öffne „Partnerfirmen“ und prüfe Unternehmensart, Firma, Ansprechpartner und vollständige Kontaktdaten. Kläre fehlende oder widersprüchliche Angaben direkt mit dem Betrieb.","Stimme die Zusammenarbeit ab und wähle den geeigneten Firmenstatus. Erst eine Freischaltung erlaubt die vorgesehene Falleinreichung.","Hinterlege eine verständliche Rückmeldung zur Prüfung. Bei Ablehnung oder Sperrung sollte der Betrieb wissen, welche Klärung erforderlich ist.","Beachte Änderungs- und Datenschutzanfragen des Partners. Ein geänderter Profilname ist nicht automatisch eine Änderung sämtlicher Firmenstammdaten."],"note":"","links":[]},{"id":"team","title":"Interne Mitarbeiter einladen & sperren","group":"Verwaltung","roles":["admin"],"summary":"Persönliche Zugänge statt geteilter Administratorkonten.","steps":["Öffne „Internes Team“ und trage den Namen und die geschäftliche E-Mail-Adresse des neuen Mitarbeiters ein.","Wähle „Zugang anlegen & Einladung senden“. Das Konto erhält eine persönliche E-Mail zur Einrichtung. Die Einladung gilt 24 Stunden.","Prüfe den angezeigten Einladungsstand. Bei abgelaufenem Link oder fehlgeschlagenem Versand nutze „Einladung erneut senden“ und kontrolliere die Adresse.","Weise dem Mitarbeiter die vorgesehenen Fälle in der Fallbearbeitung zu. Interne Gutachter erhalten Zugriff auf ihre zugewiesenen Vorgänge, nicht auf die gesamte Administration.","Bei Ausscheiden oder pausierter Mitarbeit sperre den Zugang über den Team-Eintrag. Reaktiviere ihn nur nach entsprechender Entscheidung."],"note":"","links":[]},{"id":"kanzleien","title":"Kanzleipartner & Kontaktdaten verwalten","group":"Verwaltung","roles":["admin"],"summary":"Korrekte Empfängerdaten vor dem Gutachtenversand bereitstellen.","steps":["Öffne „Kanzleipartner“. Lege eine Kanzlei mit Namen, Kontaktperson, Telefonnummer und E-Mail-Adresse an bzw. prüfe eine eingegangene Kanzleiregistrierung.","Hinterlege das passende Kanzleilogo über das angebotene Uploadfeld und kontrolliere Kontaktdaten und Aktivierungsstatus. Wähle nur tatsächlich abgestimmte Partner aus.","Ordne im Fall die vom Auftraggeber gewählte Kanzlei zu. Bei einer eigenen Kanzlei prüfe die individuell übermittelten Angaben.","Vor der dokumentierten Weitergabe müssen Auftrag und Übermittlungsberechtigung passen. Prüfe die Kanzlei erneut, bevor du den Versand bestätigst.","Die Kundeninformation nach dem Versand nutzt die hinterlegten Kanzleiangaben. Eine spätere Änderung des Verzeichnisses ersetzt nicht die Kontrolle eines bereits dokumentierten Versands."],"note":"","links":[]},{"id":"versand","title":"E-Mail-Versand prüfen & erneut freigeben","group":"Verwaltung","roles":["admin"],"summary":"Versandstatus und tatsächlichen Empfang unterscheiden.","steps":["Öffne „E-Mail-Versand“ und aktualisiere die Ansicht. Dort siehst du die erfassten Fallbenachrichtigungen mit Empfänger, Zeitpunkt und Versuchen.","„Wartet auf Versand“ bzw. „Wird versandt“ bedeutet, dass die Nachricht noch verarbeitet wird. „Vom Mailserver angenommen“ ist keine Bestätigung, dass der Empfänger sie gelesen hat.","Bei „Zustellung prüfen“ kontrolliere Empfänger und Postausgang sowie gegebenenfalls Spam beim Empfänger. Ein unklarer Ausgang kann bedeuten, dass die Nachricht bereits zugestellt wurde.","Bestätige „Versand erneut freigeben“ nur, wenn du die Zustellung geprüft hast und eine weitere E-Mail erforderlich ist. So vermeidest du unnötige doppelte Nachrichten.","Team-Einladungen werden zusätzlich unter „Internes Team“ angezeigt. Google- und Apple-Anmeldung sind nur nutzbar, wenn deren Einrichtung als verfügbar angezeigt wird."],"note":"","links":[]},{"id":"statistik","title":"Statistiken richtig lesen","group":"Konto & Unterstützung","roles":["partner","admin","appraiser"],"summary":"Zahlen beziehen sich auf die für deinen Zugang sichtbaren Vorgänge.","steps":["Im Partnerportal findest du diesen Bereich im Menü „Konto & Abrechnung“. Im internen Dashboard stehen die für deine Rolle freigegebenen Bereiche direkt in der Navigation.","Öffne „Statistiken“. Vergleiche Fallzahl, laufende Bearbeitung und freigegebene bzw. versandte Gutachten im jeweiligen Zugriffsbereich.","Der Durchschnitt bis zur Freigabe nutzt nur Vorgänge mit den erforderlichen erfassten Zeitpunkten. Ältere Fälle ohne diese Zeitstempel fließen nicht vollständig ein.","Die Monatsübersicht unterscheidet neu angelegte Vorgänge und erstmals freigegebene Gutachten. Beide Zahlen müssen deshalb nicht gleich sein.","Öffne bei Rückfragen die Fallliste und den konkreten Verlauf. Die Zeitangaben sind Kalendertage und keine zugesagte Bearbeitungsdauer."],"note":"","links":[]},{"id":"firma","title":"Firmendaten ändern & Datenexport","group":"Konto & Unterstützung","roles":["partner"],"summary":"Geschäftliche Stammdaten und persönliche Einstellungen getrennt pflegen.","steps":["Öffne im Partnerportal das Menü „Konto & Abrechnung“ und wähle den entsprechenden Bereich.","Öffne „Meine Firma“ und kontrolliere Ansprechpartner, Anschrift, Telefon, Unternehmensart und den Freigabestatus.","Sende eine Änderung der Firmendaten über das Anfragefeld an die Administration. Beschreibe die alte und die neue Angabe eindeutig.","Datenschutzanfragen kannst du ebenfalls dort an UNFALLX übermitteln. Eine Anfrage wird geprüft; sie löscht nicht sofort eigenständig die Fallakten.","„Meine Daten exportieren“ lädt die bereitgestellten Kontodaten als JSON herunter. Sichere die Datei nur auf einem geschützten Gerät.","Deinen persönlichen Profilnamen, deine Funktion und deine bevorzugte Ansicht findest du unter „Einstellungen“."],"note":"","links":[]},{"id":"einstellungen","title":"Profil, E-Mails & angemeldete Geräte","group":"Konto & Unterstützung","roles":["partner","admin","appraiser"],"summary":"Deinen eigenen Arbeitsplatz einstellen.","steps":["Im Partnerportal findest du diesen Bereich im Menü „Konto & Abrechnung“. Im internen Dashboard stehen die für deine Rolle freigegebenen Bereiche direkt in der Navigation.","Öffne „Einstellungen“. Ändere Name, Telefonnummer und Funktion und speichere das Profil. Für eine Änderung der E-Mail-Adresse kontaktiere UNFALLX.","Im Partnerportal startest du direkt mit deinen Fällen. Im internen Dashboard kannst du deine Startansicht wählen. Kompakte Tabellen sind optional; die Darstellung bleibt hell.","Du kannst Falländerungs-E-Mails für dein eigenes Konto an- oder ausschalten. Sicherheits- und Zugangs-E-Mails bleiben aktiv. Dies ersetzt nicht das Einverständnis eines zusätzlichen Kundenempfängers.","Unter „Zugang & Sicherheit“ siehst du aktive Sitzungen. Mit „Andere Geräte abmelden“ beendest du deren Anmeldungen; dein aktuelles Gerät bleibt angemeldet.","Google- oder Apple-Konten können nur verbunden werden, wenn der Anbieter eingerichtet und verfügbar ist. Für sicherheitsrelevante Änderungen kann eine erneute Anmeldung nötig sein."],"note":"","links":[]},{"id":"sicherheit","title":"Mobilnummer bestätigen & Zwei-Faktor-Anmeldung","group":"Konto & Unterstützung","roles":["partner","admin","appraiser"],"summary":"Eine bestätigte Rufnummer und zusätzlicher Anmeldeschutz sind zwei Schritte.","steps":["Öffne „Einstellungen“ bzw. mobil „Profil“ und den Abschnitt „Mobilnummer & Zwei-Faktor-Anmeldung“.","Wenn SMS verfügbar ist, trage deine deutsche Mobilnummer ein, fordere einen Code an und bestätige sie mit den sechs Ziffern aus der SMS. Nutze den aktuellen Code innerhalb seiner angezeigten Gültigkeit.","Für zusätzlichen Schutz wähle anschließend die Aktivierung der Zwei-Faktor-Anmeldung. Bestätige die geforderten Schritte mit einem frischen SMS-Code und deinem aktuellen Passwort.","Bewahre die angezeigten Wiederherstellungscodes geschützt auf. Jeder Code kann nur einmal verwendet werden. Mit neuen Codes verlieren vorherige ihre Gültigkeit.","Ist das Telefon nicht verfügbar, nutze beim Login einen Wiederherstellungscode. Danach kannst du die Sicherheit nach erneuter Prüfung verwalten. Ein bloßes Zurücksetzen des Passworts umgeht die zweite Absicherung nicht."],"note":"Steht dort „wird eingerichtet“, ist der SMS-Dienst noch nicht freigeschaltet. Die App behauptet dann keine bereits aktive SMS-Verifikation.","links":[]},{"id":"handy","title":"Partnerportal auf dem Handy nutzen","group":"Konto & Unterstützung","roles":["partner"],"summary":"Dieselben Fälle am Computer und direkt am Fahrzeug bearbeiten.","steps":["Öffne app.unfallx.com in Safari auf dem iPhone oder einem aktuellen Browser auf Android. Melde dich mit deinem bestehenden Partnerkonto an.","Die untere Navigation führt zu Start, Schäden, Provision und Profil. Im Menü findest du die zusätzlichen Funktionen. Wähle „Fall im Browser aufnehmen“, um mehrere Fotos und PDFs gemeinsam auszuwählen; je nach Gerät kannst du auch die Kamera verwenden.","Auf dem iPhone: Teilen → „Zum Home-Bildschirm“. Unter Android: Browsermenü → „Zum Startbildschirm hinzufügen“ bzw. „App installieren“, sofern angeboten. Das UNFALLX-Icon öffnet das Partnerportal.","Speichern, Laden und Hochladen benötigen eine Internetverbindung. Kontrolliere die Speicherbestätigung und lasse fehlgeschlagene Uploads nach Rückkehr der Verbindung erneut übertragen.","Lasse den Bildschirm während größerer Uploads aktiv. Warte bis alle Dateien erfolgreich übertragen sind, bevor du die Seite verlässt oder den Fall einreichst."],"note":"Die eigenständige native iPhone-App ist entwickelt; ihre App-Store-Veröffentlichung wird vorbereitet. Das mobile Browserportal ist bereits nutzbar.","links":[]},{"id":"probleme","title":"Häufige Probleme schnell lösen","group":"Konto & Unterstützung","roles":["partner","admin","appraiser"],"summary":"Die Meldung am Bildschirm zeigt, welcher Schritt noch fehlt.","steps":["„Betrieb nicht freigeschaltet“: E-Mail-Bestätigung reicht allein nicht aus. Die Administration muss die Zusammenarbeit prüfen und den Partnerbetrieb freischalten.","„Pflichtangaben fehlen“: Öffne die markierten Formularbereiche. Prüfe bedingte Felder wie Polizeiaktenzeichen bei unbekanntem Gegnerkennzeichen und die Dokumentarten der Uploads.","„Zwischenzeitlich geändert“: Der Vorgang wurde in einem anderen Fenster oder von jemand anderem gespeichert. Sichere deine noch offenen Angaben, lade den aktuellen Stand und gleiche die Änderung ab.","„Sitzung abgelaufen“: Melde dich im selben Arbeitsbereich neu an. Öffne anschließend den bestehenden Fall und kontrolliere, was bereits gespeichert wurde.","„Keine Fälle sichtbar“: Prüfe Suchfilter und Konto. Ein interner Gutachter benötigt eine Zuweisung; Partner sehen nur Fälle ihres Betriebs.","„Status lässt sich nicht ändern“: Prüfe Rolle, aktuellen Stand und Voraussetzungen wie vollständige Unterlagen, Gutachten-PDF oder Versandbestätigung. Wenn die angebotene Aktion trotzdem scheitert, sende die genaue Meldung mit Fallnummer an den Support."],"note":"","links":[]},{"id":"support","title":"Persönliche Hilfe erhalten","group":"Konto & Unterstützung","roles":["partner","admin","appraiser"],"summary":"Mit dem richtigen Kontext können wir gezielt helfen.","steps":["Schreibe an info@unfallx.com oder rufe 0176 64 365 185 an. Nenne deinen Betrieb, deinen Arbeitsbereich und bei Fallfragen die Fallnummer.","Beschreibe den letzten Schritt, den genauen Wortlaut der Meldung sowie Gerät und Browser. Ein Bildschirmfoto der Fehlermeldung kann helfen; blende nicht benötigte Kundendaten aus.","Übermittle Fotos, Dokumente und fachliche Ergänzungen möglichst in der geschützten Fallakte. Verwende Support-E-Mails nicht als ungeordneten Ersatz für eine vollständige Fallaufnahme.","Gib keine Passwörter, SMS-Codes oder persönlichen Anmeldelinks weiter. UNFALLX benötigt diese Angaben nicht zur Beschreibung eines Problems."],"note":"","links":[["E-Mail an UNFALLX","mailto:info@unfallx.com"],["UNFALLX anrufen","tel:+4917664365185"]]},{"id":"fallbereiche","title":"Schadenakte: Daten, Fotos, Status und Provision","group":"Fälle & Unterlagen","roles":["partner","admin","appraiser"],"summary":"Die Fallakte ist nach Arbeitsschritten gegliedert.","steps":["Öffne „Meine Fälle“ bzw. „Fälle“ und wähle das Fahrzeug. Oben siehst du den Bearbeitungsstand, die Zahl der Unterlagen und – je nach Berechtigung – die Provision.","„Verlauf“ zeigt die Änderungen zum Fall mit Datum. Unter „Daten“ findest du Kunden-, Fahrzeug-, Unfall- und Besichtigungsangaben; freigegebene Felder kannst du dort bearbeiten.","Unter „Fotos“ siehst du nummerierte Kacheln. Antippen öffnet die Wischvorschau; dort kannst du auch das einzelne Original herunterladen. „Alle Fotos herunterladen“ speichert sämtliche Fotos als ZIP. „PDFs & Dokumente“ bündelt die weiteren Unterlagen und bietet zusätzlich den gesamten Dateisatz als ZIP an.","Intern wird der nächste Schritt unter „Bearbeitung“ gespeichert. Ein Gutachten muss vor seiner Freigabe als PDF hinterlegt sein. Versandbestätigungen müssen den tatsächlich erfolgten Versand dokumentieren.","Administratoren legen unter „Vergütung“ das Gutachtenhonorar, den festen Nettobetrag oder Prozentanteil des Partners und die Vereinbarung fest. Der Partner sieht anschließend seinen Betrag und bestätigt die Konditionen.","Eine vorgemerkte Provision ist noch keine Auszahlung. Erst nach vollständigem Zahlungseingang, den vereinbarten Voraussetzungen und Rechnungsfreigabe kann die Auszahlung dokumentiert werden."],"note":"Partner können weder interne Notizen lesen noch ihre eigene Vergütung oder den internen Gutachtenstatus ändern.","links":[]}];

topics.push({"id": "fallablage", "title": "Fälle archivieren, löschen und wiederherstellen", "group": "Fälle & Unterlagen", "roles": ["partner", "admin", "appraiser"], "summary": "Jeder Partnerbetrieb und UNFALLX verwalten ihre eigene Fallablage unabhängig.", "steps": ["Öffne „Meine Fälle“ bzw. „Fälle“. Über „Aktuell“, „Archiv“ und „Papierkorb“ wählst du die Ablage. Suche und Statusfilter funktionieren in jeder Ablage.", "Öffne einen Fall und wähle oben „Archivieren“. Er verschwindet aus deiner aktuellen Fallliste und bleibt im Archiv erreichbar.", "Mit „Löschen“ verschiebst du den Fall nach Bestätigung in deinen Papierkorb. Es werden keine Originaldateien oder gemeinsamen Falldaten endgültig gelöscht.", "Öffne einen Fall im Archiv oder Papierkorb und wähle „Wiederherstellen“. Danach erscheint er wieder unter „Aktuell“.", "Partner ändern nur die Ablage ihres eigenen Betriebs. Administratoren ändern nur die Ablage des internen Dashboards. Interne Gutachter können die Ablage ihrer zugewiesenen Fälle ansehen; Änderungen daran übernimmt die Administration.", "Die Ablage ändert weder den Bearbeitungsstand noch die Abrechnung. Abrechnungen und Provisionen bleiben vollständig nachvollziehbar. Es werden dafür keine Fallstatus-E-Mails verschickt."], "note": "Archivieren oder Löschen aus der Ansicht storniert keinen Auftrag. Kläre Änderungen am Auftrag direkt mit UNFALLX. Eine neue Statusmeldung verschiebt den Fall nicht automatisch zurück nach „Aktuell“.", "links": []});

topics.push({id:'autoixpert',title:'Falldaten und Originale an autoiXpert übergeben',group:'Interne Bearbeitung',roles:['admin'],summary:'Die gezielte Übergabe liegt im Fall unter Bearbeitung.',steps:['Prüfe zuerst den Fall und die zugehörigen Unterlagen. Öffne unter Bearbeitung den Bereich Übergabe an autoiXpert.','Bestätige die Übermittlung und den angezeigten Preis. autoiXpert berechnet laut seiner Preisliste 1 € netto je Gutachten für Schreibzugriff. Die App ruft danach keine Gutachten über die kostenpflichtige Lese-API ab.','Lasse die Seite während der Übergabe geöffnet. Falldaten und Originaldateien werden übertragen; die Anzeige zählt die bestätigten Dateien. Interne Notizen, Aufgaben, Chat-Anhänge einschließlich Sprachnachrichten, markierte Fotokopien, fertige Gutachten, Partnerrechnungen und Auszahlungsbelege werden nicht übertragen.','Nur die Administration kann die Anlage auslösen. Das Partnerportal übermittelt ausschließlich an UNFALLX. Über Gutachten in autoiXpert öffnen gelangst du direkt zum angelegten Datensatz. Nach erfolgreicher Übergabe prüfst du die erfassten Angaben in autoiXpert und erstellst dort das Gutachten. Der Status bei UNFALLX ändert sich dadurch nicht automatisch.','Bei einer unterbrochenen Dateiübertragung kannst du fortsetzen. Bei einer unbestätigten Anlage stoppt die App, um Doppelanlagen zu vermeiden. Prüfe dann zuerst den Datensatz in autoiXpert.','Die abgeschlossene Übergabe ist eine Momentaufnahme. Spätere Änderungen werden nicht automatisch synchronisiert. Die strukturierte JSON-Fallakte und das ZIP mit Originalen stehen zusätzlich als manuelle Exporte bereit.'],note:'Keine automatische Kontaktaufnahme mit Kunden, Anwälten oder Versicherungen durch diese Übergabe.',links:[]});
topics.push({id:'arbeitsablauf',title:'Rückfragen, Aufgaben und Wiederaufnahme',group:'Fälle & Unterlagen',roles:['partner','admin','appraiser'],summary:'Gezielt ergänzen und den nächsten Schritt im Fall festhalten.',steps:['Unter Übersicht erscheinen offene Anforderungen und intern zusätzlich nächste Aufgaben. Öffne einen Eintrag, um direkt zum passenden Fallbereich zu gelangen.','UNFALLX erstellt im Fall unter Rückfragen eine konkrete Anforderung mit optionalem Termin. Der Partner lädt die Unterlagen im selben Fall hoch, ordnet sie seiner Antwort zu und sendet die Antwort zur Prüfung. UNFALLX bestätigt anschließend die Erledigung.','Interne Aufgaben mit Fälligkeitsdatum liegen unter Bearbeitung. Sie sind für Partner nicht sichtbar. Die Administration weist den zuständigen Bearbeiter zu.','Beim Erfassen speichert der Browser Angaben und ausgewählte Originaldateien lokal. Achte auf die Bestätigung der lokalen Sicherung. Nach dem Neuladen lässt sich die begonnene Aufnahme auf demselben Gerät wiederherstellen. Zum Öffnen des Portals und Einreichen ist eine Internetverbindung erforderlich.','Bei unterbrochenen Uploads erneut übertragen: Bereits bestätigte Dateien werden nicht nochmals angelegt. Ein Fall wird erst nach vollständiger Prüfung und bestätigter Dateiübertragung eingereicht.','Lokale Daten werden beim Abmelden entfernt. Verwende auf gemeinsam benutzten Geräten immer Abmelden. Browserbereinigung kann lokale Sicherungen löschen; online gespeicherte Entwürfe sind davon unabhängig.','Vergütung bündelt erwartete Beträge, vereinbarte Konditionen, Rechnungen und Auszahlungen. Vergütungen aus bestehenden Empfehlungen bleiben darunter gesondert erreichbar; neue Teilnahmen am zusätzlichen Empfehlungsprogramm sind pausiert.'],note:'Bereits eingereichte Falldaten und Originale bleiben erhalten. Archiv und Papierkorb sind weiterhin pro Betrieb und intern getrennt.',links:[]});
topics.push({id:'system',title:'System, Speicher und Verbindungen prüfen',group:'Administration',roles:['admin'],summary:'Konfiguration und tatsächliche Erreichbarkeit unterscheiden.',steps:['Öffne Verwaltung → System & Verbindungen. Die Anzeige unterscheidet eingerichtete Zugangsdaten von erfolgreich bestätigten Prüfungen.','Datenbank prüfen führt eine aktuelle Abfrage aus. Originalspeicher testen schreibt eine kleine Testdatei, liest sie mit Prüfsumme zurück und gibt sie zur sicheren Bereinigung frei.','SMTP prüfen bestätigt die Verbindung und den Zugang, sendet aber keine E-Mail. E-Mail-Versand zeigt die Annahme durch den Mailserver. Ob eine E-Mail im Posteingang liegt, muss separat geprüft werden.','Bei eindeutig abgelehnten Benachrichtigungen erfolgen höchstens vier Versuche mit Wartezeit. Bei unklarer Annahme erfolgt kein automatischer Nachversand. Prüfe Postausgang und Empfänger, bevor du den Versand erneut freigibst.','Trage Verantwortlichkeit und Sicherungsplan im Systembereich ein. Anbieter-Sicherungen und gemeinsame Wiederherstellung von Datenbank und Originalen müssen separat geprüft und protokolliert werden.'],note:'Keine Zugangsschlüssel, Passwörter oder Kundendaten in Support-Anfragen kopieren.',links:[]});
topics.push({id:'kontakte',title:'Website-Kontaktanfragen bearbeiten',group:'Administration',roles:['admin'],summary:'Anfragen und Anhänge bleiben auch bei Mailstörungen erhalten.',steps:['Öffne Verwaltung → Kontaktanfragen. Die Liste enthält die dauerhaft gespeicherten Nachrichten, Kontaktdaten und erfolgreich übernommenen Anhänge.','Öffne Anhänge über ihre Download-Schaltfläche. Zugriff haben ausschließlich Administratoren.','Falls Anhänge fehlen, erscheint ein Hinweis. Kläre die fehlenden Dateien direkt mit der anfragenden Person.','Setze die Anfrage auf In Bearbeitung oder Erledigt und ergänze eine interne Notiz.','Eine Nachricht mit unklarer SMTP-Annahme kann unter E-Mail-Versand nach Prüfung erneut freigegeben werden. Bearbeite die Anfrage auch dann, wenn keine Benachrichtigung im Posteingang erscheint.'],note:'Frühere lokale Dateisicherungen aus alten Versionen sind nicht automatisch importiert. Vorhandene Altdateien müssen separat geprüft werden.',links:[]});
const chatHelp=topics.find(t=>t.id==='nachrichten');if(chatHelp)Object.assign(chatHelp,{title:'Chat mit UNFALLX und Partnern',summary:'Ein gemeinsamer Chat pro Fall – auf dem Handy unten, am Computer über den Chat-Button.',steps:['Öffne unten Chat und suche nach Kennzeichen, Fallnummer oder Partner. Wähle den passenden Fall aus, auch wenn noch keine Nachricht vorliegt.','Schreibe deine Nachricht und ergänze bei Bedarf über Foto / PDF bis zu sechs Originaldateien mit je 25 MB. Senden überträgt Text und Anhänge gemeinsam.','Eigene Nachrichten stehen rechts, Antworten links. Ein geöffneter Chat prüft etwa alle 15 Sekunden auf neue Antworten. Aktualisieren prüft sofort.','Frühere Rückfragen und Antworten findest du im gleichen Chat unter Unterlagen & Klärungen. Die Fallakte erreichst du über Akte öffnen.','Partner sehen nur Chats ihrer eigenen Firma. Die Administration und zugewiesene interne Bearbeiter sehen die für sie freigegebenen Fälle.','Bei einer unbestätigten Übertragung bleibt die vorbereitete Nachricht erhalten. Erneutes Senden bestätigt dieselbe Nachricht, ohne sie doppelt anzulegen. Ungesendete Web-Entwürfe sind beim Verlassen nicht dauerhaft gespeichert.']});
for(const topic of topics){if(topic.id==='fallbereiche'||topic.id==='arbeitsablauf'){topic.steps=topic.steps.map(s=>s.replaceAll('Bereich Rückfragen','Chat → Unterlagen & Klärungen').replaceAll('unter Rückfragen','im Chat unter Unterlagen & Klärungen').replaceAll('Nachrichten öffnen','Chat öffnen'));}}
const labels={partner:['Partnerportal','Fälle sicher einreichen. Jeden Schritt verstehen.'],admin:['Administration','Dein Handbuch für die gesamte Fallverwaltung.'],appraiser:['Internes Team','Zugewiesene Fälle strukturiert bearbeiten.']};
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const forRole=role=>topics.filter(t=>t.roles.includes(role));
function render(role='partner',embedded=false){if(!labels[role])role='partner';const list=forRole(role),groups=[...new Set(list.map(t=>t.group))],prefix=embedded?'#hilfe/':'#';return `<div class="ux-help" data-help-root><header class="ux-help-hero"><span class="ux-help-eyebrow">UNFALLX · HILFECENTER</span><h1>Hilfe für ${role==='admin'?'die ':'das '}${(role==='appraiser'?'interne Team':labels[role][0])}.</h1><p>${labels[role][1]}</p><span class="ux-help-count">${list.length} Anleitungen · Schritt für Schritt</span></header><div class="ux-help-search"><label for="help-search">Was möchtest du wissen?</label><div><input type="search" id="help-search" placeholder="Zum Beispiel: Fotos, Passwort, Status …" autocomplete="off"><button type="button" data-help-clear aria-label="Hilfesuche zurücksetzen">Zurücksetzen</button></div><p data-help-count role="status" aria-live="polite">Alle ${list.length} Anleitungen</p></div><nav class="ux-help-index" aria-label="Hilfethemen">${groups.map((g,i)=>`<a href="${prefix}gruppe-${i}">${escape(g)}</a>`).join('')}</nav><div class="ux-help-empty" hidden>Keine passende Anleitung gefunden. Versuche „Upload“, „Anmelden“ oder „Status“ – oder kontaktiere <a href="mailto:info@unfallx.com">info@unfallx.com</a>.</div><div class="ux-help-sections">${groups.map((g,i)=>`<section data-help-group id="gruppe-${i}"><h2>${escape(g)}</h2>${list.filter(t=>t.group===g).map(t=>`<details class="ux-help-topic" id="${t.id}" data-help-topic><summary><span><strong>${escape(t.title)}</strong><small>${escape(t.summary)}</small></span><span class="ux-help-plus" aria-hidden="true">+</span></summary><div class="ux-help-answer"><ol>${t.steps.map(s=>`<li>${escape(s)}</li>`).join('')}</ol>${t.note?`<aside class="ux-help-note">${escape(t.note)}</aside>`:''}<div class="ux-help-topic-links">${t.links.map(([name,url])=>`<a href="${escape(url)}">${escape(name)} →</a>`).join('')}<a href="${prefix+t.id}" class="ux-help-permalink">Link zu dieser Anleitung</a></div></div></details>`).join('')}</section>`).join('')}</div><aside class="ux-help-support"><h2>Noch eine Frage offen?</h2><p>Nenne uns deinen Bereich und die Fallnummer. Wir helfen dir persönlich weiter.</p><a href="mailto:info@unfallx.com">info@unfallx.com</a><a href="tel:+4917664365185">0176 64 365 185</a></aside></div>`;}
function bind(root,embedded=false){const box=root.matches?.('[data-help-root]')?root:root.querySelector('[data-help-root]');if(!box)return;const input=box.querySelector('#help-search'),items=[...box.querySelectorAll('[data-help-topic]')],groups=[...box.querySelectorAll('[data-help-group]')],count=box.querySelector('[data-help-count]');const normal=s=>s.toLocaleLowerCase('de').normalize('NFD').replace(/[\u0300-\u036f]/g,'');function filter(){const q=normal(input.value.trim()),words=q.split(/\s+/).filter(Boolean);let found=0;items.forEach(el=>{const match=words.every(w=>normal(el.textContent).includes(w));el.hidden=!match;if(q&&match)el.open=true;else if(!q)el.open=false;if(match)found++;});groups.forEach(g=>g.hidden=![...g.querySelectorAll('[data-help-topic]')].some(t=>!t.hidden));count.textContent=q?found+' passende Anleitung'+(found===1?'':'en'):'Alle '+found+' Anleitungen';box.querySelector('.ux-help-empty').hidden=found>0;}
input.addEventListener('input',filter);box.querySelector('[data-help-clear]').addEventListener('click',()=>{input.value='';filter();input.focus();});function openTopic(id){id=({'mobile-schritte':'erster-fall',konto:'einstellungen'})[id]||id;const target=[...items,...groups].find(t=>t.id===id);if(!target)return;input.value='';filter();if(target.tagName==='DETAILS')target.open=true;target.scrollIntoView({block:'start',behavior:'instant'});}
box.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(!a)return;const id=a.hash.replace(embedded?'#hilfe/':'#','');if(![...items,...groups].some(t=>t.id===id))return;e.preventDefault();history.replaceState(null,'',a.hash);openTopic(id);});const id=location.hash.replace(embedded?'#hilfe/':'#','');if(id)requestAnimationFrame(()=>openTopic(id));return {openTopic};}
const routeTopics={chat:'nachrichten',system:'system',kontakte:'kontakte',verguetung:'abrechnung',requests:'arbeitsablauf',verlauf:'fallbereiche',start:'uebersicht',nachrichten:'nachrichten',unterlagen:'dokumente',provision:'abrechnung',faelle:'uebersicht',fall:'fallbereiche',neu:'erster-fall',status:'status-aendern',statistik:'statistik',empfehlungen:'empfehlungen',abrechnung:'abrechnung',firma:'firma',dokumente:'dokumente',kanzleien:'kanzleien',partner:'partner',team:'team',provisionen:'provisionen',versand:'versand',einstellungen:'einstellungen',konto:'einstellungen'};
function contextual(role,route){let id=['faelle/archiv','faelle/papierkorb'].includes(route)?'fallablage':routeTopics[route.split('/')[0]]||'orientierung';if(role==='partner'&&id==='status-aendern')id='bearbeitung';return forRole(role).some(t=>t.id===id)?id:'orientierung';}
return {forRole,render,bind,contextual};});
